+function retryAfterMs(headers: Record<string, string>): number {
+  const seconds = Number(headers['retry-after']);
+  return Number.isFinite(seconds) && seconds > 0 ? seconds * 1000 : LOGIN_RATE_LIMIT_WINDOW_MS;
