    if (k === 'select') await lab(page, l).selectOption(val); else await lab(page, l).fill(val);
  }
  if (!skip.includes('consent')) await lab(page, 'Autorizo el tratamiento de mis datos personales.').check();
}

async function fresh(browser, optionalYear = false) {
  const ctx = await browser.newContext();
  const page = await ctx.newPage();
  if (optionalYear) {
    await page.route('**/api/form-fields**', async (route) => {
      const res = await route.fetch();
      const json = await res.json();
      for (const item of json.data) if (item.key === 'vehicleYear') item.isRequired = false;
      await route.fulfill({ response: res, json });
    });
  }
  await page.goto(`${BASE}/co/datos`);
  await lab(page, 'Placa').waitFor();
  return { ctx, page };
}

(async () => {
  const browser = await chromium.launch();
  const out = {};

  {
    const { ctx, page } = await fresh(browser);
    await fillCo(page);
    await page.waitForTimeout(50);
    const d = lab(page, 'Fecha de nacimiento');
    await d.click();
    await page.keyboard.press('Backspace');
    const st = await d.evaluate((el) => ({ value: el.value, badInput: el.validity.badInput }));
    await page.keyboard.press('Tab');
    await page.waitForTimeout(100);
    const err = await d.getAttribute('aria-invalid');
    const desc = await d.getAttribute('aria-describedby');
    const storedBirth = (await stored(page)).birthDate;
    await page.getByRole('button', { name: 'Continuar' }).click();
    await page.waitForTimeout(500);
    out.P1_date_partial = { ...st, ariaInvalid: err, describedBy: desc, storedBirth, urlAfterContinuar: page.url() };
    await ctx.close();
  }

  for (const how of ['enter', 'click']) {
    const { ctx, page } = await fresh(browser, true);
    await fillCo(page, ['Modelo (año)']);
    const y = lab(page, 'Modelo (año)');
    await y.click();
    await page.keyboard.type('2015e');
    if (how === 'enter') await page.keyboard.press('Enter'); else await page.getByRole('button', { name: 'Continuar' }).click();
    await page.waitForTimeout(500);
    out[`P2_optional_${how}`] = { url: page.url(), storedYear: (await stored(page)).vehicleYear };
    await ctx.close();
  }

  {
    const results = [];
    for (let i = 0; i < 10; i++) {
      const { ctx, page } = await fresh(browser);
      await fillCo(page, ['Modelo (año)']);
      const y = lab(page, 'Modelo (año)');
      await y.click();
      await page.keyboard.type('2015', { delay: 0 });
      await page.keyboard.insertText('e');
      await page.keyboard.press('Enter');
      await page.waitForTimeout(300);
      const bad = await y.evaluate((el) => el.validity.badInput).catch(() => 'n/a');
      results.push({ url: page.url().replace(BASE, ''), storedYear: (await stored(page)).vehicleYear, badInput: bad });
      await ctx.close();
    }
    out.P3_insertText = results;
  }

  {
    let left = 0; const stores = new Set();
    for (let i = 0; i < 20; i++) {
      const { ctx, page } = await fresh(browser);
      await fillCo(page, ['Modelo (año)']);
      await lab(page, 'Modelo (año)').click();
      await page.keyboard.type('2015e', { delay: 0 });
      await page.keyboard.press('Enter');
      await page.waitForTimeout(200);
      if (!page.url().endsWith('/co/datos')) left++;
      stores.add(String((await stored(page)).vehicleYear));
      await ctx.close();
    }
    out.P4_fast_required = { navigatedAway: left, storedValues: [...stores] };
  }

  {
    let ok = 0;
    for (let i = 0; i < 10; i++) {
      const { ctx, page } = await fresh(browser);
      await fillCo(page, ['Nombre completo']);
      await lab(page, 'Nombre completo').click();
      await page.keyboard.type('Ana Prueba', { delay: 0 });
      await page.keyboard.press('Enter');
      await page.waitForURL(/planes$/, { timeout: 3000 }).then(() => ok++).catch(() => {});
      await ctx.close();
    }
    out.P5_text_then_enter = `${ok}/10 reached /planes`;
  }

  {
    const { ctx, page } = await fresh(browser);
    await lab(page, 'Modelo (año)').click();
    await page.keyboard.type('2015e');
    await page.keyboard.press('Tab');
    await page.reload();
    await lab(page, 'Placa').waitFor();
    out.P6_reload = { shown: await lab(page, 'Modelo (año)').inputValue(), stored: (await stored(page)).vehicleYear };
    await ctx.close();
  }

  console.log(JSON.stringify(out, null, 2));
  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });
