S=/private/tmp/claude-502/-Users-cristiansabogal-Proyectos-multicountry-car-insurance/067ab97b-afa7-4129-b205-146de5718a1c/scratchpad; cat > $S/probe-cl.cjs <<'EOF'
const { createRequire } = require('node:module');
const req = createRequire('/Users/cristiansabogal/Proyectos/multicountry-car-insurance/frontend/package.json');
const { chromium } = req('@playwright/test');
const esc = (t) => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const lab = (page, l) => page.getByLabel(new RegExp(`^\\s*${esc(l)}\\s*(\\*)?\\s*$`));
(async () => {
  const browser = await chromium.launch();
  const page = await (await browser.newContext()).newPage();
  await page.goto('http://localhost:8080/cl/datos');
  await lab(page, 'Patente').waitFor();
  for (const [l, v] of [['RUT','12.345.678-5'],['Nombre completo','Ana Prueba Ficticia'],['Fecha de nacimiento','1990-05-15'],['Patente','BCDF12'],['Modelo','Yaris'],['Año','2022']]) await lab(page, l).fill(v);
  for (const l of ['Ciudad','Marca']) { const opts = await lab(page, l).locator('option:not([disabled])').evaluateAll((o) => o.map((x) => x.value)); await lab(page, l).selectOption(opts[0]); }
  await lab(page, 'Acepto el tratamiento de mis datos personales.').check();
  const before = page.url();
  const d = lab(page, 'Fecha de nacimiento');
  await d.click(); await page.keyboard.press('Backspace'); await page.keyboard.press('Tab');
  await page.getByRole('button', { name: 'Continuar' }).click();
  await page.waitForTimeout(600);
  console.log(JSON.stringify({ badInput: await page.evaluate(() => document.getElementById('field-birthDate')?.validity.badInput ?? 'gone'), urlAfter: page.url() }));
  await browser.close();
})();
EOF
cd $S && node probe-cl.cjs

